$store=velvet_marketing_store(); $notice=''; $error='';
function mm_slug(string $value): string { $value=strtolower(trim($value)); $value=preg_replace('/[^a-z0-9]+/','-',$value)??''; return trim($value,'-'); }
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{velvet_marketing_verify_csrf($_POST['csrf']??null);$action=(string)($_POST['action']??'');
  if($action==='save_post'){$store->upsert('posts',['id'=>(string)($_POST['id']??''),'title'=>trim((string)($_POST['title']??'')),'slug'=>mm_slug((string)($_POST['slug']?:$_POST['title']??'')),'excerpt'=>trim((string)($_POST['excerpt']??'')),'body'=>trim((string)($_POST['body']??'')),'category'=>trim((string)($_POST['category']??'Update')),'status'=>(string)($_POST['status']??'draft'),'publish_at'=>(string)($_POST['publish_at']??gmdate('Y-m-d\TH:i'))]);$notice='Post saved.';}
  elseif($action==='save_banner'){$store->upsert('banners',['id'=>(string)($_POST['id']??''),'text'=>trim((string)($_POST['text']??'')),'url'=>trim((string)($_POST['url']??'')),'enabled'=>!empty($_POST['enabled']),'starts_at'=>(string)($_POST['starts_at']??''),'ends_at'=>(string)($_POST['ends_at']??'')]);$notice='Banner saved.';}
  elseif($action==='save_link'){$store->upsert('links',['id'=>(string)($_POST['id']??''),'label'=>trim((string)($_POST['label']??'')),'url'=>trim((string)($_POST['url']??'')),'enabled'=>!empty($_POST['enabled']),'sort'=>(int)($_POST['sort']??0)]);$notice='Link saved.';}
  elseif($action==='save_page'){$store->upsert('landing_pages',['id'=>(string)($_POST['id']??''),'title'=>trim((string)($_POST['title']??'')),'slug'=>mm_slug((string)($_POST['slug']?:$_POST['title']??'')),'eyebrow'=>trim((string)($_POST['eyebrow']??'Special Offer')),'excerpt'=>trim((string)($_POST['excerpt']??'')),'body'=>trim((string)($_POST['body']??'')),'cta_label'=>trim((string)($_POST['cta_label']??'Learn More')),'cta_url'=>trim((string)($_POST['cta_url']??'')),'enabled'=>!empty($_POST['enabled']),'starts_at'=>(string)($_POST['starts_at']??''),'ends_at'=>(string)($_POST['ends_at']??'')]);$notice='Campaign page saved.';}
  elseif($action==='save_referral'){$store->upsert('referral_codes',['id'=>(string)($_POST['id']??''),'code'=>strtoupper(preg_replace('/[^A-Za-z0-9_-]/','',(string)($_POST['code']??''))),'label'=>trim((string)($_POST['label']??'')),'enabled'=>!empty($_POST['enabled'])]);$notice='Referral code saved.';}
  elseif($action==='save_campaign'){$record=$store->upsert('campaigns',['id'=>(string)($_POST['id']??''),'subject'=>trim((string)($_POST['subject']??'')),'preheader'=>trim((string)($_POST['preheader']??'')),'body'=>trim((string)($_POST['body']??'')),'status'=>(string)($_POST['status']??'draft'),'scheduled_at'=>(string)($_POST['scheduled_at']??'')]);if(!empty($_POST['queue'])){$count=$store->queueCampaign($record['id']);$notice='Campaign saved and '.$count.' deliveries queued.';}else{$notice='Campaign saved.';}}
  elseif($action==='delete'){ $store->delete((string)$_POST['collection'],(string)$_POST['id']);$notice='Item removed.'; }
 }catch(Throwable $e){$error=$e->getMessage();}
}
$data=$store->all();$summary=$store->analyticsSummary(30);$tab=preg_replace('/[^a-z]/','',(string)($_GET['tab']??'overview'))?:'overview';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing & Publishing | Velvet Vixxen</title><link rel="stylesheet" href="/public/assets/css/marketing.css"></head><body class="marketing-admin"><main class="marketing-admin-shell"><header class="marketing-admin-header"><div><span class="marketing-eyebrow">Velvet Vixxen Admin</span><h1>Marketing, Publishing & Analytics</h1></div><a class="marketing-button" href="/admin/">Back to Admin</a></header><?php if($notice):?><div class="marketing-notice"><?=velvet_marketing_escape($notice)?></div><?php endif;?><?php if($error):?><div class="marketing-notice"><?=velvet_marketing_escape($error)?></div><?php endif;?><nav class="marketing-tabs"><?php foreach(['overview','posts','banners','campaigns','links','newsletter','referrals'] as $t):?><a href="?tab=<?=$t?>"><?=ucfirst($t)?></a><?php endforeach;?></nav>
